INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 5º DPO de uma laparotomia exploradora por trauma abdominal, um paciente apresenta saída de secreção entérica franca pela ferida operatória. O débito é de 700 ml em 24 horas. O paciente está estável, afebril e com abdome indolor. Ao realizar uma tomografia, observa-se que não existem coleções intra-abdominais bloqueadas. De acordo com a classificação de débito, esta fístula enterocutânea é considerada:", "options": {"a": "Baixo débito (< 200 ml/24h).", "b": "Médio débito (200-500 ml/24h).", "c": "Alto débito (> 500 ml/24h).", "d": "Fístula terminal.", "e": "Fístula de alto risco de mortalidade imediata."}, "answer": "c", "rationale": "As fístulas enterocutâneas são classificadas pelo débito diário. Valores acima de 500 ml/dia são considerados alto débito, o que dificulta o fechamento espontâneo e predispõe a distúrbios hidroeletrolíticos graves.", "option_rationales": {"a": "Incorreta. Baixo débito é abaixo de 200 ml.", "b": "Incorreta. Médio débito é entre 200 e 500 ml.", "c": "Correta. Definição técnica para débito > 500 ml.", "d": "Incorreta. Não existe essa classificação por volume.", "e": "Incorreta. Alto débito aumenta o risco, mas não define mortalidade imediata per se."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Fístula", "Enterocutânea"]}', 71, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 38 anos, submetido a cirurgia de controle de danos (Damage Control) por trauma abdominal grave, encontra-se com abdome aberto (peritoneostomia) protegido por bolsa de Bogotá. Qual a principal complicação a longo prazo esperada caso o fechamento da aponeurose não seja possível nas primeiras semanas?", "options": {"a": "Hérnia incisional gigante (Hérnia ventral planejada).", "b": "Deiscência de pele.", "c": "Atelectasia recidivante.", "d": "Infecção urinária crônica.", "e": "Fístula biliar primária."}, "answer": "a", "rationale": "Quando o abdome é mantido aberto por necessidade clínica (choque, coagulopatia, edema de alças), a retração da aponeurose impede o fechamento primário posterior, resultando em uma grande hérnia ventral que precisará de correção tardia.", "option_rationales": {"a": "Correta. Consequência esperada da laparostomia.", "b": "Incorreta. A pele pode ser fechada com enxertos, mas o defeito aponeurótico persiste.", "c": "Incorreta. Atelectasia é complicação respiratória aguda.", "d": "Incorreta. Sem relação direta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia de Trauma", "Pós-operatório", "Abdome Aberto", "Complicações"]}', 72, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Após uma tireoidectomia total, o paciente desenvolve estridor inspiratório imediato após a extubação na sala de cirurgia. O cirurgião observa que não há hematoma cervical ou edema de glote visível. Qual a causa provável considerando a manipulação bilateral do pescoço?", "options": {"a": "Crise asmática.", "b": "Lesão bilateral do nervo laríngeo recorrente.", "c": "Hipocalcemia tardia.", "d": "Fístula traqueal.", "e": "Edema pulmonar por pressão negativa."}, "answer": "b", "rationale": "A lesão bilateral do nervo laríngeo recorrente causa a paralisia de ambas as pregas vocais em posição mediana (fechadas), resultando em obstrução aguda da via aérea e necessidade de reintubação ou traqueostomia.", "option_rationales": {"a": "Incorreta. Estridor é sinal de via aérea superior, asma dá sibilância expiratória.", "b": "Correta. Emergência pós-tireoidectomia bilateral.", "c": "Incorreta. Hipocalcemia raramente causa estridor imediato após extubação sem outros sinais (laringoespasmo pode ocorrer, mas o nervo lesionado é mais provável após dissecção bilateral).", "d": "Incorreta.", "e": "Incorreta. Ocorre após obstrução, não é a causa da obstrução primária."}, "difficulty": "media", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Estridor", "Emergência"]}', 73, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes submetidos a esplenectomia, a sepse fulminante pós-esplenectomia (OPSI - Overwhelming Post-Splenectomy Infection) pode ocorrer mesmo anos após a cirurgia. Qual o organismo mais frequentemente isolado nesses casos e que apresenta a maior mortalidade?", "options": {"a": "Staphylococcus aureus.", "b": "Streptococcus pneumoniae (Pneumococo).", "c": "Escherichia coli.", "d": "Pseudomonas aeruginosa.", "e": "Clostridium difficile."}, "answer": "b", "rationale": "O Pneumococo é responsável por mais de 50-70% dos casos de OPSI. A falta do baço prejudica a opsonização e remoção de germes encapsulados.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Principal patógeno no asplênico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Esplenectomia", "OPSI"]}', 74, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 65 anos, tabagista, hipertenso e diabético, é submetido a uma revascularização infra-inguinal com enxerto de veia safena. No 2º DPO, apresenta ausência de pulsos distais (antes presentes), pé frio e dor intensa em repouso. Qual a conduta diagnóstica imediata sugerida pelo protocolo de complicações vasculares?", "options": {"a": "Aguardar 12 horas para ver se a circulação colateral melhora.", "b": "Realizar Angiotomografia ou Arteriografia de urgência por suspeita de trombose do enxerto.", "c": "Aumentar a infusão de insulina.", "d": "Realizar teste de esforço.", "e": "Drenar a ferida operatória."}, "answer": "b", "rationale": "A perda súbita de pulsos e sinais de isquemia crítica no pós-operatório de revascularização indica falha/trombose do enxerto. Exige diagnóstico rápido e trombectomia ou revisão cirúrgica para salvar o membro.", "option_rationales": {"a": "Incorreta. A isquemia aguda leva à necrose muscular em poucas horas.", "b": "Correta. Padrão-ouro para avaliação de patência de anastomoses e enxertos.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Vascular", "Pós-operatório", "Isquemia Aguda", "Trombose de Enxerto"]}', 75, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "O uso de anti-inflamatórios não esteroidais (AINEs) no pós-operatório de anastomoses gastrointestinais tem sido questionado em alguns estudos por qual potencial risco teórico?", "options": {"a": "Aumento do risco de deiscência de anastomose por inibição das prostaglandinas envolvidas na cicatrização.", "b": "Risco de pancreatite aguda.", "c": "Desenvolvimento de catarata precoce.", "d": "Hipercalemia severa imediata.", "e": "Redução do débito de fístulas pancreáticas."}, "answer": "a", "rationale": "Embora controverso, alguns estudos sugerem que os AINEs (especialmente os não-seletivos e em altas doses) podem interferir na microcirculação e síntese de colágeno no sítio da anastomose, aumentando o risco de vazamentos.", "option_rationales": {"a": "Correta. Principal preocupação teórica e clínica discutida em cirurgia colorretal.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta. AINEs podem afetar o rim, mas a preocupação cirúrgica local é a anastomose.", "e": "Incorreta. Eles não influenciam beneficamente o débito de fístulas."}, "difficulty": "moderada", "tags": ["Cirurgia Geral", "Pós-operatório", "Anastomose", "AINEs"]}', 76, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia bariátrica (Bypass em Y-de-Roux), o paciente apresenta-se no 4º DPO com dor abdominal súbita, vômitos e parada de eliminação de gazes. O cirurgião suspeita de uma hérnia interna. Qual o local anatômico mais frequente para a ocorrência desta hérnia específica nesta técnica cirúrgica?", "options": {"a": "Espaço de Petersen (entre o mesentério do membro alimentar e o mesocólon transverso).", "b": "Forame de Winslow.", "c": "Hiato esofágico.", "d": "Canal femoral.", "e": "Janela da vesícula biliar."}, "answer": "a", "rationale": "As hérnias internas são complicações mecânicas graves após Bypass gástrico, ocorrendo em espaços criados pela transposição das alças intestinais, sendo o espaço de Petersen o mais comum.", "option_rationales": {"a": "Correta. Localização clássica de hérnia interna pós-bariátrica.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cirurgia Bariátrica", "Pós-operatório", "Hérnia Interna", "Obstrução"]}', 77, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal causa de febre persistente no pós-operatório tardio (> 7 dias) em pacientes que permanecem com cateter venoso central por longo período?", "options": {"a": "Febre inflamatória de parede.", "b": "Infecção de corrente sanguínea associada a cateter (IPCS).", "c": "Atelectasia de lobo superior.", "d": "Reação ao fio de sutura.", "e": "Hipoglicemia rebote."}, "answer": "b", "rationale": "A presença de cateter central é um dos maiores fatores de risco para bacteremia hospitalar tardia. Exige coleta de hemoculturas (periférica e do cateter) para diagnóstico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Causa frequente de febre após a primeira semana.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Infecção", "Cateter Central"]}', 78, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes idosos, a desidratação pós-operatória pode ser mascarada pela falta de sensação de sede. Qual o parâmetro laboratorial e clínico inicial que melhor ajuda a detectar a desidratação precoce antes da queda da pressão arterial?", "options": {"a": "Concentração de sódio e densidade urinária elevada associada a xerostomia (mucosas secas).", "b": "Queda do hematócrito.", "c": "Ausculta de estertores crepitantes.", "d": "Leucocitose.", "e": "Bradicardia."}, "answer": "a", "rationale": "A oligúria concentrada (urina escura) e mucosas secas ocorrem antes da hipotensão (choque). O sódio tende a subir na desidratação simples (hipernatremia relativa).", "option_rationales": {"a": "Correta. Sinais precoces de déficit de volume.", "b": "Incorreta. Hematócrito subiria (hemoconcentração).", "c": "Incorreta. Estertores sugerem sobrecarga hídrica.", "d": "Incorreta.", "e": "Incorreta. Desidratação causa taquicardia compensatória."}, "difficulty": "facil", "tags": ["Geriátria", "Pós-operatório", "Desidratação", "Monitorização"]}', 79, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 10º DPO de uma cirurgia de ressecção de pâncreas, nota-se que o dreno abdominal está saindo conteúdo esbranquiçado, leitoso. O paciente não tem febre ou dor. A análise do líquido mostra Triglicerídeos de 250 mg/dL e presença de quilomícrons. Qual a complicação?", "options": {"a": "Fístula gástrica.", "b": "Ascite quilosa pós-operatória.", "c": "Fístula pancreática bioquimicamente relevante.", "d": "Infecção por Pseudomonas.", "e": "Coleção purulenta."}, "answer": "b", "rationale": "A ascite quilosa ocorre pela lesão de canais linfáticos retroperitoneais volumosos durante a linfadenectomia peripancreática. O diagnóstico é dado pela dosagem de triglicerídeos no líquido de drenagem.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Diagnóstico compatível com o aspecto leitoso e triglicerídeos elevados.", "c": "Incorreta. Fístula pancreática teria amilase alta, mas não necessariamente gordura leitosa.", "d": "Incorreta. Pseudomonas produz pus verde/azulado, não leitoso.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Ascite Quilosa", "Complicações Linfáticas"]}', 80, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia abdominal desenvolve quadro de vômitos no 3º DPO. O cirurgião decide passar uma sonda nasogástrica. Qual a principal complicação metabólica (distúrbio ácido-básico e eletrolítico) esperada caso a drenagem gástrica seja volumosa e prolongada?", "options": {"a": "Acidose metabólica hiponatrêmica.", "b": "Alcalose metabólica hipoclorêmica e hipocalêmica.", "c": "Acidose respiratória.", "d": "Hipoalbuminemia.", "e": "Hipercalcemia."}, "answer": "b", "rationale": "O suco gástrico é rico em H+, Cl- e K+. A perda dessses elementos leva à alcalose e queda do cloro e potássio.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Quadro clássico de perdas gástricas.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Equilíbrio Ácido-Básico", "SNG"]}', 81, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a conduta inicial recomendada para um hematoma de ferida operatória pequeno, não expansivo e que não causa dor importante no 2º DPO?", "options": {"a": "Reabertura imediata da ferida no centro cirúrgico.", "b": "Observação e aplicação de compressas mornas.", "c": "Punção aspirativa imediata no leito.", "d": "Prescrição de Warfarina.", "e": "Debridamento da aponeurose."}, "answer": "b", "rationale": "Hematomas pequenos e estáveis tendem a ser reabsorvidos pelo organismo. Compressas mornas podem auxiliar na liquefação e absorção tardia. A invasão deve ser evitada para não transformar um hematoma estéril em abscesso.", "option_rationales": {"a": "Incorreta. Conduta agressiva para caso pequeno/estável.", "b": "Correta. Manejo conservador padrão.", "c": "Incorreta. Risco de introduzir infecção.", "d": "Incorreta. Anticoagulante pioraria o hematoma.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Hematoma", "Manejo"]}', 82, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em um paciente submetido a cirurgia bariátrica, o desenvolvimento de nistagmo, ataxia e confusão mental no 15º DPO agressivo sugere deficiência aguda de qual micronutriente?", "options": {"a": "Vitamina B12.", "b": "Tiamina (Vitamina B1).", "c": "Vitamina D.", "d": "Ferro.", "e": "Zinco."}, "answer": "b", "rationale": "A Tríade de Wernicke (confusão, ataxia e nistagmo) deve ser suspeitada em bariátricos com vômitos persistentes no pós-op que param de absorver tiamina.", "option_rationales": {"a": "Incorreta. B12 causa sintomas neurológicos mais tardios (meses/anos).", "b": "Correta. Encefalopatia de Wernicke aguda.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Bariátrica", "Pós-operatório", "Nutrição", "Deficiência"]}', 83, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 5º DPO de uma cirurgia de grande porte, o paciente apresenta dor e edema em panturrilha direita. Após diagnóstico de TVP, qual a duração mínima recomendada de anticoagulação para um primeiro episódio de TVP provocada por cirurgia?", "options": {"a": "15 dias.", "b": "3 meses.", "c": "1 ano.", "d": "Para o resto da vida.", "e": "Apenas durante a internação."}, "answer": "b", "rationale": "Para episódios de TVP com fator de risco transitório (como cirurgia de grande porte), recomenda-se anticoagulação por um período de 3 meses.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Diretriz padrão da ACCP.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Vascular", "Pós-operatório", "TVP", "Tratamento"]}', 84, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente submetido a prostatectomia radical. No 3º DPO, apresenta-se com dor de início súbito em região inguinal e testicular, associada a febre de 38,5°C e disúria. Ao exame físico: testículo esquerdo edemaciado, doloroso e com reflexo cremastérico ausente. Qual o diagnóstico diferencial mais importante excluir?", "options": {"a": "Torção testicular pós-operatória.", "b": "Orquiepididimite bacteriana.", "c": "Cálculo renal.", "d": "Hernia recidivante.", "e": "Edema escrotal fisiológico."}, "answer": "a", "rationale": "Embora a orquiepididimite seja mais comum após manipulação urinária, a ausência do reflexo cremastérico e o início súbito da dor devem sempre fazer o cirurgião descartar a torção testicular, que é uma emergência cirúrgica.", "option_rationales": {"a": "Correta. Diagnóstico clínico que exige exclusão rápida.", "b": "Incorreta. Diferencial comum, mas reflexo cremastérico costuma estar presente.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Fisiológico não daria febre e dor intensa."}, "difficulty": "moderada", "tags": ["Urologia", "Pós-operatório", "Torção Testicular", "Dor Escrotal"]}', 85, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A ocorrência de dor precordial súbita no 3º DPO de cirurgia abdominal em paciente cardiopata deve ser investigada. Qual a enzima cardíaca (marcador de necrose miocárdica) que melhor auxilia o diagnóstico no pós-operatório por ser menos influenciada pelo trauma da musculatura esquelética da cirurgia?", "options": {"a": "CK-Total.", "b": "TGO/AST.", "c": "Troponina I ou T.", "d": "Mioglobina.", "e": "Creatinina."}, "answer": "c", "rationale": "A troponina é altamente específica para o músculo cardíaco, enquanto CK-MB e CK-Total se elevam em qualquer cirurgia que envolva incisão muscular.", "option_rationales": {"a": "Incorreta. Se eleva muito no trauma cirúrgico.", "b": "Incorreta. Muito inespecífica.", "c": "Correta. Marcar de escolha em pós-operatórios.", "d": "Incorreta. Primeira a subir, mas muito inespecífica (sobe no trauma muscular).", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Pós-operatório", "IAM", "Diagnóstico"]}', 86, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a laparotomia por trauma apresenta no 3º DPO saída de líquido esverdeado pelo dreno abdominal. A amilase desse líquido é de 10.000 U/L. O cirurgião suspeita de lesão iatrogênica ou traumática não vista de qual órgão?", "options": {"a": "Vesícula Biliar.", "b": "Duodeno ou Pâncreas.", "c": "Gastro-omentais.", "d": "Rim.", "e": "Bexiga."}, "answer": "b", "rationale": "A amilase muito elevada no líquido de drenagem abdominal é característica de fístulas originadas do pâncreas ou da secreção duodenal.", "option_rationales": {"a": "Incorreta. Biliar teria bilirrubina alta, amilase baixa.", "b": "Correta. Fontes de amilase digestiva/exócrina.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Fístula", "Pâncreas"]}', 87, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma lobectomia hepática, observa-se que o paciente apresenta tremores nas mãos (asterixe), sonolência e desorientação. Laboratório mostra Bilirrubinas normais, mas Amônia elevada. Qual a provável complicação e o tratamento inicial?", "options": {"a": "Encefalopatia hepática; lactulona e restrição de proteínas.", "b": "AVC isquêmico; heparina.", "c": "Insuficiência renal; diálise.", "d": "Meningite; antibióticos.", "e": "Abstinência alcoólica; benzodiazepínicos."}, "answer": "a", "rationale": "A remoção de grande massa hepática pode reduzir a capacidade de desintoxicação da amônia, levando à encefalopatia metabólica.", "option_rationales": {"a": "Correta. Quadro clínico de insuficiência hepática pós-operatória.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Diferencial em etilistas, mas amônia alta aponta para o fígado."}, "difficulty": "media", "tags": ["Cirurgia Hepato-Biliar", "Pós-operatório", "Encefalopatia", "Fígado"]}', 88, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes idosos, qual medicação profilática costuma ser evitada para náuseas e vômitos pós-operatórios (PONV) devido ao risco de sintomas extrapiramidais e agitação?", "options": {"a": "Ondansetrona.", "b": "Metoclopramida.", "c": "Dexametasona.", "d": "Difenidramina.", "e": "Bromoprida."}, "answer": "b", "rationale": "A metoclopramida é um antagonista dopaminérgico que pode causar acatisia e reações extrapiramidais em idosos. Ondansetrona é geralmente preferida nesse grupo.", "option_rationales": {"a": "Incorreta. Considerada segura.", "b": "Correta. Droga a ser evitada ou usada com muita cautela no idoso.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Também é antagonista D2, mas metoclopramida é a mais citada."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "PONV", "Farmacologia"]}', 89, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a revascularização miocárdica queixa-se no 4º DPO de dor em região de base de pulmão esquerdo, associada a febre baixa e tosse seca. Ausculta pulmonar com discretos estertores e Raio-x com pequena opacidade em cunha. Qual a complicação comum nessa cirurgia pela manipulação do nervo frênico ou pleurotomia?", "options": {"a": "Pneumonia grave.", "b": "Atelectasia de lobo inferior esquerdo.", "c": "Embolia pulmonar.", "d": "Infarto esplênico.", "e": "Pleurite por trauma cirúrgico e atelectasia por hipoventilação álgica."}, "answer": "e", "rationale": "Ocorre com frequência após retirada da artéria mamária interna, levando a dor pleurítica e pequena atelectasia basal esquerda.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta, embora ocorra, a pleurite inflamatória é o diferencial doloroso.", "c": "Incorreta.", "d": "Incorreta.", "e": "Correta. Evolução típica e benigna na maioria dos casos."}, "difficulty": "media", "tags": ["Cirurgia Cardíaca", "Pós-operatório", "Pleurotomia", "Complicações"]}', 90, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal causa de ''anemia'' falsa (queda do hematócrito) nas primeiras 24 horas de pós-operatório de pacientes que receberam grande volume de cristaloides?", "options": {"a": "Hemólise traumática.", "b": "Hemorragia interna silenciosa.", "c": "Hemodiluição.", "d": "Insuficiência medular por anestesia.", "e": "Deficiência de ferro aguda."}, "answer": "c", "rationale": "A reposição volêmica agressiva dilui os eritrócitos. Antes de assumir sangramento, deve-se avaliar o balanço hídrico e a estabilidade hemodinâmica.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Fenômeno laboratorial comum.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Anemia", "Hemodiluição"]}', 91, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma herniorrafia inguinal, a ocorrência de edema e equimose na base do pênis e bolsa escrotal é frequente. Qual a orientação correta a ser dada ao paciente pelo cirurgião?", "options": {"a": "Sugerir reoperação imediata.", "b": "Tranquilizar o paciente informando que é um hematoma/equimose benigno que gravitou para o tecido frouxo escrotal, recomendando suspensório escrotal.", "c": "Prescrever antibiótico de largo espectro.", "d": "Indicar orquidopexia.", "e": "Aplicar gelo diretamente na pele escrotal por 48 horas ininterruptas."}, "answer": "b", "rationale": "O sangue do espaço subcutâneo inguinal desce por gravidade para o escroto. Se não houver dor extrema ou expansão rápida, o tratamento é conservador.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Conduta clínica de tranquilização e suporte.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Gelo em excesso na pele escrotal fina pode causar lesão térmica local."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Herniorrafia", "Complicações Locais"]}', 92, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes tabagistas inveterados graves submetidos a grandes cirurgias, a interrupção do tabagismo deve Idealmente ocorrer quanto tempo antes do procedimento para redução real do risco de complicações respiratórias e de cicatrização?", "options": {"a": "24 horas antes.", "b": "1 semana antes.", "c": "Pelo menos 4 a 8 semanas antes.", "d": "Pode parar no dia da cirurgia se quiser.", "e": "Interromper 48 horas antes é prejudicial por aumentar o catarro."}, "answer": "c", "rationale": "Embora parar 24h antes reduza a carboxiemoglobina, a melhora real da função ciliar e cardiovascular exige pelo menos 4 a 8 semanas de abstinência.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Tempo ideal para benefício pré-operatório.", "d": "Incorreta.", "e": "Incorreta, embora exista essa lenda, qualquer tempo sem fumar é benéfico para oxigenação, mas o prazo longo é o ideal para complicação de ferida."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pré-operatório", "Tabagismo", "Cicatrização"]}', 93, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 3º DPO de uma cirurgia abdominal, o dreno de sucção fechada (ex: Jackson-Pratt) parou de funcionar subitamente. O paciente apresenta abaulamento doloroso sob a cicatriz. Qual a primeira manobra recomendada antes de remover o dreno?", "options": {"a": "Corte de 2 cm da pele.", "b": "Ordenha do dreno e verificação de obstrução por coágulo ou fibrina no sistema.", "c": "Injeção de 50 ml de ar no dreno.", "d": "Lavagem interna do dreno com álcool 70%.", "e": "Solicitar raio-x de abdome."}, "answer": "b", "rationale": "Obstrução mecânica do lúmen do dreno é comum. A ordenha restaura o vácuo e a drenagem antes de se assumir que o dreno perdeu sua utilidade.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Manobra básica de enfermagem/medicina cirúrgica.", "c": "Incorreta. Perigoso e infecta o dreno.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Drenos", "Cuidados"]}', 94, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia colorretal desenvolve oligúria no 1º DPO. A pressão arterial e o débito cardíaco estão normais. A relação Ureia/Creatinina sérica está elevada (> 20:1) e o sódio urinário é baixo (< 20 mEq/L). Qual a classificação da insuficiência renal aguda?", "options": {"a": "NTA (Renal Intrínseca).", "b": "Pós-renal (Obstrutiva).", "c": "Pré-renal (Funcional).", "d": "Glomerulonefrite.", "e": "Nefropatia tónixa por contraste."}, "answer": "c", "rationale": "A relação elevada de ureia/creatina e o sódio urinário baixo indicam que o rim está reabsorvendo avidamente água e sódio para compensar uma queda na perfusão relativa ou hipovolemia, caracterizando a fase pré-renal.", "option_rationales": {"a": "Incorreta. Na NTA o sódio urinário estaria alto (> 40).", "b": "Incorreta. Obstrutiva exige imagem mostrando dilatação.", "c": "Correta. Diagnóstico laboratorial compatível.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Nefrologia", "Pós-operatório", "IRA", "Pré-renal"]}', 95, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente idosa, 80 anos, no 2º DPO de fratura de fêmur, começa a gritar e tentar sair do leito à noite, não reconhecendo os familiares. Durante o dia, apresenta-se sonolenta e apática. Qual o diagnóstico?", "options": {"a": "Início de Doença de Alzheimer.", "b": "Delirium (tipo misto).", "c": "Sindrome do por-do-sol pura.", "d": "Reação ao frio.", "e": "Depressão maior pós-traumática."}, "answer": "b", "rationale": "O delirium é caracterizado pela flutuação do nível de consciência e déficit de atenção, sendo muito comum no pós-operatório de idosos (especialmente ortopedia).", "option_rationales": {"a": "Incorreta. Alzheimer é crônico.", "b": "Correta. Característica de flutuação e agudização em idoso operado.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Depressão não causa flutuação do nível de consciência aguda."}, "difficulty": "facil", "tags": ["Geriátria", "Pós-operatório", "Delirium", "Idoso"]}', 96, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em qual situação clínica no pós-operatório o uso de sonda nasogástrica (SNG) está formalmente indicado de forma terapêutica?", "options": {"a": "Rotina após qualquer laparotomia.", "b": "Paciente com vômitos persistentes, distensão abdominal e evidência de obstrução mecânica ou íleo severo.", "c": "Para alimentar todos os pacientes que não querem comer nas primeiras 12h.", "d": "Apenas se o paciente tiver febre.", "e": "Para monitorar o pH gástrico profilaticamente."}, "answer": "b", "rationale": "A SNG não deve ser usada de rotina, mas sim nos casos de obstrução ou íleo dilatado para descompressão e conforto do paciente.", "option_rationales": {"a": "Incorreta. Prática obsoleta e prejudicial.", "b": "Correta. Indicação terapêutica estabelecida.", "c": "Incorreta. Dieta enteral exige sonda posicionada pós-pilórica ou gástrica, mas não como descompressão.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "SNG", "Indicações"]}', 97, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a tireoidectomia total apresenta hipocalcemia sintomática no 2º DPO. O médico prescreve cálcio endovenoso. Qual o cuidado principal na infusão de gluconato de cálcio para evitar complicações cardíacas?", "options": {"a": "Infusão rápida em bólus (menos de 1 minuto).", "b": "Infusão lenta (10-20 minutos) e monitorização se possível, para evitar bradicardia ou assistolia.", "c": "Misturar o cálcio com bicarbonato de sódio na mesma seringa.", "d": "Não usar em pacientes cardiopatas.", "e": "Apenas via oral é segura."}, "answer": "b", "rationale": "A infusão rápida de cálcio pode causar arritmias graves. Deve ser diluído e infundido lentamente.", "option_rationales": {"a": "Incorreta. Risco de arritmia fatal.", "b": "Correta. Prática de segurança na administração de reposição eletrolítica.", "c": "Incorreta. O cálcio precipita em contato com bicarbonato.", "d": "Incorreta.", "e": "Incorreta. Hipocalcemia sintomática exige via venosa inicial."}, "difficulty": "media", "tags": ["Clinica Cirúrgica", "Pós-operatório", "Segurança do Paciente", "Cálcio"]}', 98, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 3º DPO de uma cirurgia abdominal, observa-se que o dreno abdominal exterioriza secreção marrom, com odor fétido e presença de bolhas de ar. O paciente apresenta peritonismo em andar superior do abdome. Qual a provável fonte desta deiscência?", "options": {"a": "Fístula gástrica.", "b": "Fístula de cólon (fetalóide).", "c": "Fístula urinária.", "d": "Hematoma infectado.", "e": "Seroma puro."}, "answer": "b", "rationale": "Conteúdo marrom, fétido e com gás é patognomônico de saída de conteúdo fecal, indicando deiscência de anastomose de cólon.", "option_rationales": {"a": "Incorreta. Gástrica seria mais clara/biliar ou tipo borra de café.", "b": "Correta. Descrição clássica de fístula estercorácea.", "c": "Incorreta. Urina não tem odor fétido fecal e bolhas de ar (a menos que haja fístula colovesical).", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Deiscência", "Fístula Colônica"]}', 99, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes vítimas de grandes queimaduras ou grandes traumas submetidos a cirurgias sucessivas, a deficiência de qual componente nutricional está mais associada à deiscência de ferida e retardo na granulação?", "options": {"a": "Vitamina C e Proteínas.", "b": "Sódio.", "c": "Gordura insaturada.", "d": "Carboidratos simples.", "e": "Potássio."}, "answer": "a", "rationale": "A formação de colágeno exige aporte proteico adequado (aminoácidos) e vitamina C como cofator na hidroxilação da prolina e lisina.", "option_rationales": {"a": "Correta. Base da cicatrização.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Cicatrização", "Nutrição"]}', 100, 'draft')
